SELECT json_build_object('outbox',(SELECT coalesce(json_agg(x ORDER BY id),'[]') FROM (SELECT id,event_type,payload,published_at FROM outbox WHERE (payload->>'user_id')::int=(SELECT id FROM users WHERE username='mhsuji')) x),'notifications',(SELECT coalesce(json_agg(x ORDER BY outbox_id),'[]') FROM (SELECT id,outbox_id,subject FROM notifications WHERE user_id=(SELECT id FROM users WHERE username='mhsuji')) x));